INSERT INTO `wp_options` VALUES (9801,'_site_transient_wpmdb_licence_response_1','{\"features\":[],\"addons_available\":\"1\",\"addons_available_list\":{\"wp-migrate-db-pro-media-files\":2351,\"wp-migrate-db-pro-cli\":3948,\"wp-migrate-db-pro-multisite-tools\":7999,\"wp-migrate-db-pro-theme-plugin-files\":36287},\"addon_list\":{\"wp-migrate-db-pro-media-files\":{\"type\":\"feature\",\"name\":\"Media Files\",\"desc\":\"Allows you to push and pull your files in the Media Library between two WordPress installs. It can compare both libraries and only migrate those missing or updated, or it can do a complete copy of one site\\u2019s library to another. <a href=\\\"https:\\/\\/deliciousbrains.com\\/wp-migrate-db-pro\\/doc\\/media-files-addon\\/?utm_campaign=addons%252Binstall&utm_source=MDB%252BPaid&utm_medium=insideplugin\\\">More Details &rarr;<\\/a>\",\"version\":\"2.1.0\",\"beta_version\":false,\"tested\":\"5.9.3\"},\"wp-migrate-db-pro-cli\":{\"type\":\"feature\",\"name\":\"CLI\",\"desc\":\"Integrates WP Migrate with WP-CLI allowing you to run migrations from the command line:<code>wp migratedb &lt;push|pull&gt; &lt;url&gt; &lt;secret-key&gt;<\\/code> <code>[--find=&lt;strings&gt;] [--replace=&lt;strings&gt;] ...<\\/code> <a href=\\\"https:\\/\\/deliciousbrains.com\\/wp-migrate-db-pro\\/doc\\/cli-addon\\/?utm_campaign=addons%252Binstall&utm_source=MDB%252BPaid&utm_medium=insideplugin\\\">More Details &rarr;<\\/a>\",\"required\":\"1.4b1\",\"version\":\"1.6.0\",\"beta_version\":false,\"tested\":\"5.9.3\"},\"wp-migrate-db-pro-multisite-tools\":{\"type\":\"feature\",\"name\":\"Multisite Tools\",\"desc\":\"Export a subsite as an SQL file that can then be imported as a single site install. <a href=\\\"https:\\/\\/deliciousbrains.com\\/wp-migrate-db-pro\\/doc\\/multisite-tools-addon\\/?utm_campaign=addons%252Binstall&utm_source=MDB%252BPaid&utm_medium=insideplugin\\\">More Details &rarr;<\\/a>\",\"required\":\"1.5-dev\",\"version\":\"1.4.1\",\"beta_version\":false,\"tested\":\"5.9.3\"},\"wp-migrate-db-pro-theme-plugin-files\":{\"type\":\"feature\",\"name\":\"Theme & Plugin Files\",\"desc\":\"Allows you to push and pull your theme and plugin files between two WordPress installs. <a href=\\\"https:\\/\\/deliciousbrains.com\\/wp-migrate-db-pro\\/doc\\/theme-plugin-files-addon\\/?utm_campaign=addons%252Binstall&utm_source=MDB%252BPaid&utm_medium=insideplugin\\\">More Details &rarr;<\\/a>\",\"required\":\"1.8.2b1\",\"version\":\"1.2.0\",\"beta_version\":false,\"tested\":\"5.9.3\"}},\"form_url\":\"https:\\/\\/api.deliciousbrains.com\\/?wc-api=delicious-brains&request=submit_support_request&licence_key=&product=wp-migrate-db-pro\",\"license_name\":\"Developer\",\"display_name\":\"No\",\"user_email\":\"\",\"upgrade_url\":\"https:\\/\\/deliciousbrains.com\\/my-account\\/license-upgrade\\/\",\"support_contacts\":[\"\"],\"support_email\":\"support@deliciousbrains.com\",\"addon_content\":{\"wp-migrate-db-pro-media-files\":{\"install_url\":\"https:\\/\\/deliciousbrains.com\\/wp-admin\\/network\\/update.php?action=install-plugin&plugin=wp-migrate-db-pro-media-files&_wpnonce=a8e6fbcc40\",\"download_url\":\"https:\\/\\/api.deliciousbrains.com\\/?wc-api=delicious-brains&request=download&licence_key=&slug=wp-migrate-db-pro-media-files&site_url=http:\\/\\/deliciousbrains.com\"},\"wp-migrate-db-pro-cli\":{\"install_url\":\"https:\\/\\/deliciousbrains.com\\/wp-admin\\/network\\/update.php?action=install-plugin&plugin=wp-migrate-db-pro-cli&_wpnonce=474c233df5\",\"download_url\":\"https:\\/\\/api.deliciousbrains.com\\/?wc-api=delicious-brains&request=download&licence_key=&slug=wp-migrate-db-pro-cli&site_url=http:\\/\\/deliciousbrains.com\"},\"wp-migrate-db-pro-multisite-tools\":{\"install_url\":\"https:\\/\\/deliciousbrains.com\\/wp-admin\\/network\\/update.php?action=install-plugin&plugin=wp-migrate-db-pro-multisite-tools&_wpnonce=c58e6d4f3c\",\"download_url\":\"https:\\/\\/api.deliciousbrains.com\\/?wc-api=delicious-brains&request=download&licence_key=&slu