,\"source\":\"library\"}},\"elements\":[],\"widgetType\":\"image\"}],\"isInner\":true},{\"id\":\"8ca665a\",\"elType\":\"container\",\"settings\":{\"flex_direction\":\"column\",\"content_width\":\"full\",\"width\":{\"unit\":\"%\",\"size\":45},\"_flex_size\":\"grow\"},\"elements\":[{\"id\":\"de3230f\",\"elType\":\"widget\",\"settings\":{\"content_width\":\"full\",\"title\":\"Message from Our President & Founder Mario Nieves\",\"__globals__\":{\"title_color\":\"globals\\/colors?id=3197874\",\"_background_color\":\"globals\\/colors?id=88133c5\",\"_border_color\":\"globals\\/colors?id=4478c39\"},\"align\":\"left\",\"_margin\":{\"unit\":\"px\",\"top\":\"0\",\"right\":\"0\",\"bottom\":\"0\",\"left\":\"0\",\"isLinked\":false},\"_padding\":{\"unit\":\"px\",\"top\":\"15\",\"right\":\"30\",\"bottom\":\"15\",\"left\":\"30\",\"isLinked\":false},\"_background_background\":\"classic\",\"_border_border\":\"solid\",\"_border_width\":{\"unit\":\"px\",\"top\":\"2\",\"right\":\"2\",\"bottom\":\"2\",\"left\":\"2\",\"isLinked\":true},\"_box_shadow_box_shadow_type\":\"yes\"},\"elements\":[],\"widgetType\":\"heading\"},{\"id\":\"e86c0ba\",\"elType\":\"widget\",\"settings\":{\"content_width\":\"full\",\"editor\":\"<p>Thank you for visiting the home of the Latin American<br \\/>Motorcycle Association (L.A.M.A.) and the International<br \\/>Motorcycle Association (I.M.A.).<br \\/><br \\/>Through these pages, you will learn more about being part of the Best Riders Association in the World!<\\/p><p>We welcome working people from all walks of life to explore the world with us while enjoying the motorcycling lifestyle, spreading peace and love and making lifelong friendships.<\\/p><p><br \\/>Let\\u2019s Ride!<br \\/>Best,<\\/p><p>Mario Nieves<\\/p>\",\"_padding\":{\"unit\":\"px\",\"top\":\"0\",\"right\":\"30\",\"bottom\":\"0\",\"left\":\"30\",\"isLinked\":false},\"__globals__\":{\"typography_typography\":\"globals\\/typography?id=text\",\"text_color\":\"\"},\"text_color\":\"#FFFFFF\",\"typography_typography\":\"custom\",\"typography_font_family\":\"Roboto\",\"typography_font_size\":{\"unit\":\"rem\",\"size\":1.5,\"sizes\":[]},\"typography_font_weight\":\"300\"},\"elements\":[],\"widgetType\":\"text-editor\"}],\"isInner\":true}],\"isInner\":false},{\"id\":\"b113291\",\"elType\":\"container\",\"settings\":{\"flex_direction\":\"column\",\"flex_justify_content\":\"center\",\"flex_align_items\":\"center\",\"padding\":{\"unit\":\"px\",\"top\":\"40\",\"right\":\"20\",\"bottom\":\"80\",\"left\":\"20\",\"isLinked\":false},\"flex_gap\":{\"column\":\"40\",\"row\":\"40\",\"isLinked\":true,\"unit\":\"px\",\"size\":40}},\"elements\":[{\"id\":\"1809e98\",\"elType\":\"container\",\"settings\":{\"content_width\":\"full\",\"custom_css\":\"selector{\\n    background:linear-gradient(to right, var(--e-global-color-cae35c9) 0, var(--e-global-color-cae35c9) 33%,var(--e-global-color-4671584) 33%, var(--e-global-color-4671584) 66%, #fff 66%, #fff 100%);\\n}\",\"width\":{\"unit\":\"px\",\"size\":300,\"sizes\":[]},\"min_height\":{\"unit\":\"px\",\"size\":10,\"sizes\":[]},\"padding\":{\"unit\":\"px\",\"top\":\"0\",\"right\":\"0\",\"bottom\":\"0\",\"left\":\"0\",\"isLinked\":true}},\"elements\":[],\"isInner\":true},{\"id\":\"9ee2b35\",\"elType\":\"widget\",\"settings\":{\"content_width\":\"full\",\"title\":\"Get Connected With L.A.M.A. Today\",\"__globals__\":{\"title_color\":\"globals\\/colors?id=3197874\",\"_background_color\":\"globals\\/colors?id=88133c5\",\"_border_color\":\"globals\\/colors?id=4478c39\"},\"align\":\"left\",\"_margin\":{\"unit\":\"px\",\"top\":\"0\",\"right\":\"0\",\"bottom\":\"0\",\"left\":\"0\",\"isLinked\":false},\"_padding\":{\"unit\":\"px\",\"top\":\"15\",\"right\":\"30\",\"bottom\":\"15\",\"left\":\"30\",\"isLinked\":false},\"_background_background\":\"classic\",\"_border_border\":\"solid\",\"_border_width\":{\"unit\":\"px\",\"top\":\"2\",\"right\":\"2\",\"bottom\":\"2\",\"left\":\"2\",\"isLinked\":true},\"_box_shadow_box_shadow_type\":\"yes\"},\"elements\":[],\"widgetType\":\"heading\"},{\"id\":\"c72588e\",\"elType\":\"widget\",\"settings\":{\"content_width\":\"full\",\"text\":\"Contact Us\",\"align\":\"center\",\"text_padding\":{\"unit\":\"px\",\"top\":\"15\",\"right\":\"30\",\"bottom\":\"15\",\"left\":\"30\",\"isLinked\":false},\"__globals__\":{\"background_color\":\"globals\\/colors?id=4478c39\",\"button_text_color\":\"globals\\/colors?id=88133c5\",\"typography_typography\":\"globals\\/typography?id=98ba919\"}},\"elements\":[],\"widgetType\":\"button\"}],\"isInner\":false}]');
