INSERT INTO `wp_postmeta` VALUES (5128,581,'_elementor_data','[{\"id\":\"7f80c18e\",\"elType\":\"container\",\"settings\":{\"flex_direction\":\"column\",\"padding\":{\"unit\":\"px\",\"top\":\"20\",\"right\":\"20\",\"bottom\":\"20\",\"left\":\"20\",\"isLinked\":true}},\"elements\":[{\"id\":\"aa6fea9\",\"elType\":\"widget\",\"settings\":{\"content_width\":\"full\",\"image_size\":\"full\",\"width\":{\"unit\":\"%\",\"size\":100,\"sizes\":[]},\"height\":{\"unit\":\"px\",\"size\":700,\"sizes\":[]},\"image\":{\"url\":\"http:\\/\\/test.local\\/wp-content\\/uploads\\/2024\\/10\\/LAMA_Group_Ride_Bogota_2023.jpg\",\"id\":461,\"size\":\"\",\"alt\":\"\",\"source\":\"library\"}},\"elements\":[],\"widgetType\":\"image\"}],\"isInner\":false},{\"id\":\"1e72b446\",\"elType\":\"container\",\"settings\":{\"flex_direction\":\"column\",\"padding\":{\"unit\":\"px\",\"top\":\"60\",\"right\":\"20\",\"bottom\":\"60\",\"left\":\"20\",\"isLinked\":false},\"flex_align_items\":\"center\"},\"elements\":[{\"id\":\"77db3cda\",\"elType\":\"container\",\"settings\":{\"content_width\":\"full\",\"flex_direction\":\"row\",\"padding\":{\"unit\":\"px\",\"top\":\"0\",\"right\":\"0\",\"bottom\":\"0\",\"left\":\"0\",\"isLinked\":true},\"flex_gap\":{\"column\":\"50\",\"row\":\"50\",\"isLinked\":true,\"unit\":\"px\",\"size\":50}},\"elements\":[{\"id\":\"4cc652fa\",\"elType\":\"container\",\"settings\":{\"content_width\":\"full\",\"flex_direction\":\"column\",\"padding\":{\"unit\":\"px\",\"top\":\"0\",\"right\":\"0\",\"bottom\":\"0\",\"left\":\"0\",\"isLinked\":true},\"width\":{\"unit\":\"%\",\"size\":40,\"sizes\":[]}},\"elements\":[{\"id\":\"67cf256f\",\"elType\":\"widget\",\"settings\":{\"content_width\":\"full\",\"title\":\"History of L.A.M.A,\",\"__globals__\":{\"title_color\":\"globals\\/colors?id=3197874\",\"_background_color\":\"globals\\/colors?id=88133c5\",\"_border_color\":\"globals\\/colors?id=4478c39\"},\"align\":\"center\",\"_margin\":{\"unit\":\"px\",\"top\":\"0\",\"right\":\"0\",\"bottom\":\"0\",\"left\":\"0\",\"isLinked\":false},\"_padding\":{\"unit\":\"px\",\"top\":\"30\",\"right\":\"30\",\"bottom\":\"29\",\"left\":\"30\",\"isLinked\":false},\"_background_background\":\"classic\",\"_border_border\":\"solid\",\"_border_width\":{\"unit\":\"px\",\"top\":\"2\",\"right\":\"2\",\"bottom\":\"2\",\"left\":\"2\",\"isLinked\":true},\"_box_shadow_box_shadow_type\":\"yes\"},\"elements\":[],\"widgetType\":\"heading\"},{\"id\":\"ffa1a06\",\"elType\":\"widget\",\"settings\":{\"content_width\":\"full\",\"editor\":\"<p>L.A.M.A. was founded by Mario Nieves in June of 1977 in Chicago\\u2019s notorious Humboldt Park neighborhood. Nieves was inspired to create an inclusive group for motorcycle enthusiasts when he noticed the public perception of motorcycle riders was frequently negative, unlike when he was growing up in Puerto Rico and motorcyclists were considered part of the fabric of the community. He attributes the negative perception to the portrayal of bikers in Hollywood movies and set out to change it.<\\/p>\",\"__globals__\":{\"typography_typography\":\"globals\\/typography?id=text\",\"text_color\":\"globals\\/colors?id=3197874\"},\"_padding\":{\"unit\":\"px\",\"top\":\"0\",\"right\":\"30\",\"bottom\":\"0\",\"left\":\"30\",\"isLinked\":false}},\"elements\":[],\"widgetType\":\"text-editor\"}],\"isInner\":true},{\"id\":\"727fd06c\",\"elType\":\"container\",\"settings\":{\"content_width\":\"full\",\"padding\":{\"unit\":\"px\",\"top\":\"0\",\"right\":\"0\",\"bottom\":\"0\",\"left\":\"0\",\"isLinked\":true},\"width\":{\"unit\":\"%\",\"size\":60,\"sizes\":[]},\"flex_align_items\":\"center\",\"flex_gap\":{\"column\":\"0\",\"row\":\"0\",\"isLinked\":true,\"unit\":\"px\",\"size\":0}},\"elements\":[{\"id\":\"134c1d29\",\"elType\":\"widget\",\"settings\":{\"content_width\":\"full\",\"image\":{\"url\":\"http:\\/\\/test.local\\/wp-content\\/uploads\\/2024\\/10\\/Couple_Riding_with_Puerto_Rican_Flag_-_Edit_out_LAMA_Station-1.jpg\",\"id\":462,\"size\":\"\",\"alt\":\"\",\"source\":\