INSERT INTO `wp_posts` VALUES (613,1,'2024-10-07 20:04:11','2024-10-07 20:04:11','<a href=\"http://lama.local/wp-content/uploads/2024/10/Dama-on-bike-with-helmet.jpg\" data-elementor-open-lightbox=\"yes\" data-elementor-lightbox-title=\"Dama on bike with helmet\" data-e-action-hash=\"#elementor-action%3Aaction%3Dlightbox%26settings%3DeyJpZCI6NjE4LCJ1cmwiOiJodHRwOlwvXC9sYW1hLmxvY2FsXC93cC1jb250ZW50XC91cGxvYWRzXC8yMDI0XC8xMFwvRGFtYS1vbi1iaWtlLXdpdGgtaGVsbWV0LmpwZyJ9\">\n							<img src=\"http://lama.local/wp-content/uploads/elementor/thumbs/Dama-on-bike-with-helmet-qv84goqw55wzpdrbq3smzk9xbz69brdk7gla04f1xk.jpg\" title=\"Dama on bike with helmet\" alt=\"Dama on bike with helmet\" loading=\"lazy\" />								</a>\n			<h2>WE RIDE OUR OWN!</h2>		\n		<p>The female riders “Damas de L.A.M.A.” are an integral part of the Latin American Motorcycle Association and have an equal role. They are well known for riding their own motorcycles, riding long distances, and competing in Moto-Touring Championships.</p>		\n														<a href=\"http://lama.local/wp-content/uploads/2024/10/Damas-group-in-Columbia_JJA.jpg\" data-elementor-open-lightbox=\"yes\" data-elementor-lightbox-title=\"Damas group in Columbia_JJA\" data-e-action-hash=\"#elementor-action%3Aaction%3Dlightbox%26settings%3DeyJpZCI6NjE5LCJ1cmwiOiJodHRwOlwvXC9sYW1hLmxvY2FsXC93cC1jb250ZW50XC91cGxvYWRzXC8yMDI0XC8xMFwvRGFtYXMtZ3JvdXAtaW4tQ29sdW1iaWFfSkpBLmpwZyJ9\">\n							<img width=\"800\" height=\"600\" src=\"http://lama.local/wp-content/uploads/2024/10/Damas-group-in-Columbia_JJA-1024x768.jpg\" alt=\"\" srcset=\"http://lama.local/wp-content/uploads/2024/10/Damas-group-in-Columbia_JJA-1024x768.jpg 1024w, http://lama.local/wp-content/uploads/2024/10/Damas-group-in-Columbia_JJA-300x225.jpg 300w, http://lama.local/wp-content/uploads/2024/10/Damas-group-in-Columbia_JJA-768x576.jpg 768w, http://lama.local/wp-content/uploads/2024/10/Damas-group-in-Columbia_JJA-1536x1152.jpg 1536w, http://lama.local/wp-content/uploads/2024/10/Damas-group-in-Columbia_JJA-600x450.jpg 600w, http://lama.local/wp-content/uploads/2024/10/Damas-group-in-Columbia_JJA.jpg 2048w\" sizes=\"(max-width: 800px) 100vw, 800px\" />								</a>\n														<a href=\"http://lama.local/wp-content/uploads/2024/10/LAMA-Clermont-STURGIS-cool-pic.jpg\" data-elementor-open-lightbox=\"yes\" data-elementor-lightbox-title=\"LAMA Clermont STURGIS - cool pic\" data-e-action-hash=\"#elementor-action%3Aaction%3Dlightbox%26settings%3DeyJpZCI6NjIwLCJ1cmwiOiJodHRwOlwvXC9sYW1hLmxvY2FsXC93cC1jb250ZW50XC91cGxvYWRzXC8yMDI0XC8xMFwvTEFNQS1DbGVybW9udC1TVFVSR0lTLWNvb2wtcGljLmpwZyJ9\">\n							<img src=\"http://lama.local/wp-content/uploads/elementor/thumbs/LAMA-Clermont-STURGIS-cool-pic-qv84he4jvma8g5hgzejdoh7k2z132errjl8w1rvisw.jpg\" title=\"LAMA Clermont STURGIS &#8211; cool pic\" alt=\"LAMA Clermont STURGIS - cool pic\" loading=\"lazy\" />								</a>\n														<a href=\"http://lama.local/wp-content/uploads/2024/10/Damas-de-LAMA-1.jpg\" data-elementor-open-lightbox=\"yes\" data-elementor-lightbox-title=\"Damas de LAMA-1\" data-e-action-hash=\"#elementor-action%3Aaction%3Dlightbox%26settings%3DeyJpZCI6NjI0LCJ1cmwiOiJodHRwOlwvXC9sYW1hLmxvY2FsXC93cC1jb250ZW50XC91cGxvYWRzXC8yMDI0XC8xMFwvRGFtYXMtZGUtTEFNQS0xLmpwZyJ9\">\n							<img width=\"1080\" height=\"966\" src=\"http://lama.local/wp-content/uploads/2024/10/Damas-de-LAMA-1.jpg\" alt=\"\" srcset=\"http://lama.local/wp-content/uploads/2024/10/Damas-de-LAMA-1.jpg 1080w, http://lama.local/wp-content/uploads/2024/10/Damas-de-LAMA-1-300x268.jpg 300w, http://lama.local/wp-content/uploads/2024/10/Damas-de-LAMA-1-1024x916.jpg 1024w, http://lama.local/wp-content/uploads/2024/10/Damas-de-LAMA-1-768x687.jpg 768w, http://lama.local/wp-content/uploads/2024/10/Damas-de-LAMA-1-600x537.jpg 600w\" sizes=\"(max-width: 1080px) 100vw, 1080px\" />								</a>\n														<a href=\"http://lama.local/wp-content/uploads/2024/10/LAMA-Women.jpg\" data-elementor-open-lightbox=\"yes\" data-elementor-lightbox-title=\"LAMA - Women\" data-e-action-hash=\"#elementor-action%3Aaction%3Dlightbox%26settings%3DeyJpZCI6NjI1LCJ1cmwiOiJodHRwOlwvXC9sYW1hLmxvY2FsXC93cC1jb250ZW50XC91cGxvYWRzXC8yMDI0XC8xMFwvTEFNQS1Xb21lbi5qcGcifQ%3D%3D\">\n							<img src=\"http://lama.local/wp-content/uploads/elementor/thumbs/LAMA-Women-qv869kjtwgqj4difungjloudihddnlyjglqvkq7qfc.jpg\" title=\"LAMA &#8211; Women\" alt=\"LAMA - Women\" loading=\"lazy\" />								</a>\n														<a href=\"http://lama.local/wp-content/uploads/2024/10/damas2.png\" data-elementor-open-lightbox=\"yes\" data-elementor-lightbox-title=\"damas2\" data-e-action-hash=\"#elementor-action%3Aaction%3Dlightbox%26settings%3DeyJpZCI6NjI2LCJ1cmwiOiJodHRwOlwvXC9sYW1hLmxvY2FsXC93cC1jb250ZW50XC91cGxvYWRzXC8yMDI0XC8xMFwvZGFtYXMyLnBuZyJ9\">\n							<img src=\"http://lama.local/wp-content/uploads/elementor/thumbs/damas2-qv86a3clp5g9kkr4svl2zk3le6spxk1676sl69fuyw.png\" title=\"damas2\" alt=\"damas2\" loading=\"lazy\" />								</a>\n			<h2>GET CONNECTED WITH L.A.M.A. TODAY!</h2>		\n			<a href=\"#\">\n									Contact Us\n					</a>','Damas De L.A.M.A.','','publish','closed','closed','','damas-de-l-a-m-a','','','2024-10-08 00:33:18','2024-10-08 00:33:18','',0,'http://lama.local/?page_id=613',0,'page','',0);
INSERT INTO `wp_posts` VALUES (614,1,'2024-10-07 20:04:11','2024-10-07 20:04:11','<h5>Visit The Florida Motorcycle Safety Program (FMSP), Our Partners In Keeping Riders Safe On The Roads.</h5>\r\n<a href=\"http://fl-msp.com\">\r\nClick Here To Visit FL-MSP.com\r\n</a>\r\n<h2>L.A.M.A.\'s Lookin\' Out For Each Other</h2>\r\nThe Latin American Motorcycle Association wants the roads to be safe for everyone. That\'s why all L.A.M.A. meetings contain a safety segment and our officers present free safety courses at least twice a year.\r\n\r\n<img src=\"http://lama.local/wp-content/uploads/2024/10/LAMA_Safety_Course_Tampa-1024x671.jpg\" sizes=\"(max-width: 800px) 100vw, 800px\" srcset=\"http://lama.local/wp-content/uploads/2024/10/LAMA_Safety_Course_Tampa-1024x671.jpg 1024w, http://lama.local/wp-content/uploads/2024/10/LAMA_Safety_Course_Tampa-300x196.jpg 300w, http://lama.local/wp-content/uploads/2024/10/LAMA_Safety_Course_Tampa-768x503.jpg 768w, http://lama.local/wp-content/uploads/2024/10/LAMA_Safety_Course_Tampa-600x393.jpg 600w, http://lama.local/wp-content/uploads/2024/10/LAMA_Safety_Course_Tampa.jpg 1376w\" alt=\"\" width=\"800\" height=\"524\" />\r\n<h5>L.A.M.A. Safety Course - Tampa, FL</h5>\r\n<h2>Take The Rider Survey!</h2>\r\nhttps://www.youtube.com/watch?v=bC0RqC04an4\r\n<a href=\"#\">\r\nSharable Video!\r\n</a>','Damas De L.A.M.A.','','inherit','closed','closed','','613-revision-v1','','','2024-10-07 20:04:11','2024-10-07 20:04:11','',613,'http://lama.local/?p=614',0,'revision','',0);
